import java.lang.annotation.*;
import java.util.*;

public class Ex04 {
    @Retention(RetentionPolicy.RUNTIME)
    @interface Component { String value() default ""; }

    static class Scanner {
        List<Class<?>> scan(List<Class<?>> all) {
            List<Class<?>> found = new ArrayList<>();
            for (Class<?> c : all) if (c.isAnnotationPresent(Component.class)) found.add(c);
            return found;
        }
    }
    @Component static class UserService {}
    @Component static class OrderService {}
    static class Helper {} // 不是组件
    public static void main(String[] args) {
        Scanner sc = new Scanner();
        List<Class<?>> candidates = sc.scan(List.of(UserService.class, OrderService.class, Helper.class));
        System.out.println("scanned components: " + candidates.size());
        for (Class<?> c : candidates) System.out.println(" - " + c.getSimpleName());
    }
}
